contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (10) + (10));
        require(address(this).balance >= 10, "not enough balance");

        // Make the bank this contract by having it play once.
        c.play{value: 10}(); if (__ESBMC_reverted()) return;

        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;

        bool reverted;
        c.play{value: 10}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;

        assert(reverted || afterC >= afterPot);
    }

    receive() external payable {}
}

