contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 other) internal {
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 10);
        try c.play{value: 10}() {} catch { return; }
        uint256 beforePot;
        try c.pot() returns (uint256 __r) { beforePot = __r; } catch { return; }
        uint beforeC = address(c).balance;
        bool reverted;
        try c.play{value: 10}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        uint afterC = address(c).balance;
        assertTrue(reverted || afterC >= afterPot);
    }

    function testFuzz_run(uint256 other) public {
        _run(other);
    }

